// Package platform declares, for each rule that walks another package's type, a type every build declares and windows
// declares its own way where the rule looks, as os and syscall do.
package platform

import "time"

// stamp holds the time a Stamped reaches through it.
type stamp struct{ time.Time }

// Size is the same method on every type a value of which the interface row hands to a non-empty interface.
func (*Printed) Size() int { return 0 }

// Size is the same in every build.
func (*Locked) Size() int { return 0 }

// Size is the same in every build.
func (*Encoded) Size() int { return 0 }

// Size is the same in every build.
func (*Hidden) Size() int { return 0 }

// Size is the same in every build.
func (*Channeled) Size() int { return 0 }
